package lib

import (
	"errors"
	"strings"
	"testing"
)

// The expected hashes are SHA-256 of the user-data / network-config strings that
// server/src/lib/incus-config-vm.ts produces for the same inputs. They were
// generated by running the real TypeScript through tsx against the canary source
// (and the Go output was diffed byte for byte against the dumped payloads before
// the hashes were pinned, so a failure here means the two modules diverged).
func TestIncusConfigVMGenerateMatchesNodeByteForByte(t *testing.T) {
	cases := []struct {
		name            string
		params          IncusConfigVMParams
		wantUserData    string
		wantNetworkData string
		wantFragments   []string
		absentFragments []string
	}{
		{
			name:   "ubuntu-dhcp",
			params: IncusConfigVMParams{InstanceName: "vm-1", ImageAlias: "ubuntu/noble", RootPassword: "p@ss w0rd"},
			// No network record at all → DHCP netplan keyed on the eth0 MAC.
			wantUserData:    "efe6658e8df4999f99c86736e894961802174fa18d5229c7e434a44fb89da4bc",
			wantNetworkData: "a08417744ce3df9261489c8941b39f6d9e42f55a9a770e7476fc81de63818b8a",
			wantFragments: []string{
				"#cloud-config\npackage_update: true\npackage_upgrade: false\nhostname: vm-1\nmanage_etc_hosts: true\n",
				"packages:\n  - qemu-guest-agent\n  - openssh-server\n  - curl\n  - ca-certificates\n\nusers:\n",
				// No ssh key → an empty line between the root shell and chpasswd.
				"    shell: /bin/bash\n\nchpasswd:\n  expire: false\n  list:\n    - 'root:p@ss w0rd'\n",
				"      SSH_KEY=\"\"\n      ROOT_PASSWORD='p@ss w0rd'\n      DEFAULT_USERS=\"root ubuntu\"\n      SSH_SERVICE=\"ssh\"\n",
				`      retry_cmd "DEBIAN_FRONTEND=noninteractive apt-get update" && retry_cmd "DEBIAN_FRONTEND=noninteractive apt-get install -y --no-install-recommends qemu-guest-agent openssh-server curl ca-certificates" || true`,
				"      rm -f \"/etc/ssh/sshd_config.d/00-incudal-auth.conf\" 2>/dev/null || true\n",
				"      if [ \"ubuntu\" != \"alpine\" ]; then\n",
				"      systemctl unmask ssh || true\n      systemctl enable ssh 2>/dev/null || true\n",
				"      systemctl enable serial-getty@ttyS0.service || true\n      systemctl restart serial-getty@ttyS0.service || true\n",
				// The IPv4-only guard is unconditional.
				"      net.ipv6.conf.${PRIMARY_IFACE}.disable_ipv6 = 1\n",
				"      echo \"Running user custom commands...\"\n      : # No extra commands\n",
				`      macaddress: "02:a0:68:ba:c3:7d"`,
				"    dhcp4: true\n    dhcp6: false\n    accept-ra: false\n    link-local: [ ipv4 ]\n",
			},
			absentFragments: []string{
				"ssh_authorized_keys",
				"TARGET_IPV6",
				"incus_eth1",
				"gateway4",
			},
		},
		{
			name: "ubuntu-static-v4-ssh",
			params: IncusConfigVMParams{
				InstanceName: "vm-2", ImageAlias: "ubuntu/noble", RootPassword: "pa'ss\\word",
				SSHKey:  incusConfigStrPtr("ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIExampleKeyBlobHere user@host"),
				Network: &IncusConfigStaticNetwork{IPAddress: "10.10.1.100/24", Gateway: "10.10.1.1"},
			},
			wantUserData:    "2cde25f8bcb75b9279abe5e096d78e2d8b4d51fa96b2753289979093ce5e9767",
			wantNetworkData: "a2adb9ad57fc62f968dd370c02ee115a857be81778686b29e4784f67bbd19d8f",
			wantFragments: []string{
				// Shell single-quote escaping and YAML single-quote escaping differ.
				`ROOT_PASSWORD='pa'"'"'ss\word'`,
				"    - 'root:pa''ss\\word'",
				// The key sits under the root user block, with the blank line preserved.
				"    lock_passwd: false\n    shell: /bin/bash\n    ssh_authorized_keys:\n      - ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIExampleKeyBlobHere user@host\n\nchpasswd:",
				"      printf '%s\\n' \"$SSH_KEY\" > \"$home_dir/.ssh/authorized_keys\"\n",
				"    addresses:\n      - 10.10.1.100/24\n    gateway4: 10.10.1.1\n    nameservers:\n      addresses:\n        - 10.10.0.1\n",
			},
			absentFragments: []string{"incus_eth1", "dhcp4: true"},
		},
		{
			name: "debian-dualstack-custom-dns",
			params: IncusConfigVMParams{
				InstanceName: "vm-3", ImageAlias: "debian/12", RootPassword: "pw",
				Network: &IncusConfigStaticNetwork{
					IPAddress: "10.10.2.5/24", Gateway: "10.10.2.1", DNS: []string{"1.1.1.1", "8.8.8.8"},
					IPv6Address: "2001:db8::5/64", IPv6DNS: []string{"2606:4700:4700::1111", "2001:4860:4860::8888"},
				},
			},
			wantUserData:    "1721415fd07956e9c63a352ef6f96756fa59f45419ff145db267bba32dde27c2",
			wantNetworkData: "da993a56b8bf20aa51ca31b04245b6589a4f88ef7a0d20e15ecb3f502b566af1",
			wantFragments: []string{
				// Dual NIC → both MACs, and the routed IPv6 gateway is fe80::1.
				`      macaddress: "02:67:4e:68:1d:82"`,
				`      macaddress: "02:37:f4:24:88:0d"`,
				"        - 1.1.1.1\n        - 8.8.8.8\n",
				"  incus_eth1:\n",
				"      - 2001:db8::5/64\n    routes:\n      - to: ::/0\n        via: fe80::1\n        on-link: true\n",
				"        - 2606:4700:4700::1111\n        - 2001:4860:4860::8888\n",
				// Routed IPv6 turns on the persistent route guard.
				"      echo \"Installing persistent IPv6 default-route guard...\"\n",
				"      TARGET_IPV6=\"2001:db8::5\"\n",
				"      ip -6 route replace default via fe80::1 dev \"${IPV6_IFACE}\" metric 100 onlink >/dev/null 2>&1 || true\n",
			},
		},
		{
			name: "alpine-v6-no-prefix",
			params: IncusConfigVMParams{
				InstanceName: "vm-4", ImageAlias: "alpine/3.20", RootPassword: "alpinepw",
				Network: &IncusConfigStaticNetwork{IPAddress: "10.10.3.9/24", Gateway: "10.10.3.1", IPv6Address: "2001:db8::9"},
			},
			wantUserData:    "1962cff3b9e2bfcd29cebf6449a8a58cde42f97a313a773cf33eb0f56e3afe77",
			wantNetworkData: "08b20424e81fa8937bdc07add7ba89b8b12f0304dc60d463e5b8ef6fd9af3ba0",
			wantFragments: []string{
				// Alpine: no package list → package_update false, apk install command.
				"package_update: false\n",
				"      DEFAULT_USERS=\"root\"\n      SSH_SERVICE=\"sshd\"\n",
				`      retry_cmd "apk update" && retry_cmd "apk add --no-cache qemu-guest-agent openssh-server openssh-keygen curl ca-certificates shadow" || retry_cmd "apk add --no-cache qemu-guest-agent openssh curl ca-certificates shadow" || true`,
				// openrc: inittab serial console and rc-update service block.
				"      if [ -f /etc/inittab ] && ! grep -q '^ttyS0::respawn:/sbin/getty -L ttyS0 115200 vt100$' /etc/inittab 2>/dev/null; then\n",
				"      [ -f /etc/init.d/sshd ] && rc-update add sshd default 2>/dev/null || true\n",
				// No UsePAM in alpine's drop-in.
				"      ChallengeResponseAuthentication no\n      EOF\n",
				// An IPv6 address without a prefix length gets /128.
				"      - 2001:db8::9/128\n",
			},
			absentFragments: []string{
				"packages:\n",
				"      UsePAM yes\n      EOF\n",
				"systemctl enable serial-getty@ttyS0.service",
			},
		},
		{
			name: "rocky8-custom-cmds",
			params: IncusConfigVMParams{
				InstanceName: "vm-5", ImageAlias: "rockylinux/8", RootPassword: "r0cky",
				ExtraShellCommands: "  echo \"hello\"\n\n  touch /tmp/x  \n",
				NetworkMode:        "nat_ipv6_nat",
				Network:            &IncusConfigStaticNetwork{IPAddress: "10.10.4.2/24", Gateway: "10.10.4.1"},
			},
			wantUserData:    "c79048ec7f45840bb916296ff3a0ff1b5ce49f66c44e0a1eb8acb0f94d42fc65",
			wantNetworkData: "b57578bc81f174e5784b66fb590800743bb78c38c9d098ae176ee650d89048ef",
			wantFragments: []string{
				// rhel8 → yum and the distro user appended to root/cloud-user.
				"      DEFAULT_USERS=\"root cloud-user rocky\"\n",
				`      retry_cmd "yum install -y qemu-guest-agent openssh-server curl ca-certificates" || true`,
				// Custom commands are trimmed as a block but keep their inner layout.
				"      echo \"Running user custom commands...\"\n      echo \"hello\"\n\n        touch /tmp/x\n",
			},
			absentFragments: []string{": # No extra commands", "TARGET_IPV6"},
		},
		{
			name: "alma9-seed-differs",
			params: IncusConfigVMParams{
				InstanceName: "vm-6", InstanceIDSeed: "pi-abcdef", ImageAlias: "almalinux/9", RootPassword: "pw",
				SSHKey:  incusConfigStrPtr("ssh-rsa AAAAB3NzaC1yc2EAAAADAQABAAABgQCexample root@x"),
				Network: &IncusConfigStaticNetwork{IPAddress: "10.10.5.2/24", Gateway: "10.10.5.1", IPv6Address: "2001:db8::6/64"},
			},
			wantUserData:    "c1711b86978169e2a8f4a43b8b4f8778ac1be5239ce667bae41a871ea9156ccf",
			wantNetworkData: "4ba3664ab44daf60da7c126ab7d01c97679c83a04d9c1f632996d8419bf8e20a",
			wantFragments: []string{
				// The seed, not the instance name, drives both MACs.
				`      macaddress: "02:a8:b5:1a:cc:8d"`,
				`      macaddress: "02:d9:c3:36:f7:80"`,
				"      DEFAULT_USERS=\"root cloud-user almalinux\"\n",
				`      retry_cmd "dnf install -y qemu-guest-agent openssh-server curl ca-certificates" || true`,
			},
			absentFragments: []string{"02:a0:68:ba:c3:7d"},
		},
		{
			name:            "fedora",
			params:          IncusConfigVMParams{InstanceName: "vm-7", ImageAlias: "fedora/40", RootPassword: "pw"},
			wantUserData:    "c3adb0e94511d8d4d1a8692a3a5c8e3e2093df39472eda8fd9862ec93ac27cb6",
			wantNetworkData: "c4949ed6aa0235632d52334a473df5c689c65be8510b92b3288e1eab87c27207",
			wantFragments: []string{
				"      DEFAULT_USERS=\"root cloud-user fedora\"\n",
				`      retry_cmd "dnf install -y qemu-guest-agent openssh-server curl ca-certificates" || true`,
			},
		},
		{
			name:            "oracle8",
			params:          IncusConfigVMParams{InstanceName: "vm-8", ImageAlias: "oracle/8", RootPassword: "pw"},
			wantUserData:    "6453cdd443868aa97fdf105795793251d4e57416151ee56a659d0b58f965e96f",
			wantNetworkData: "81aa504c465ca13bb0f94fda7c0233f1267d5649cc74f84c49e4915faada8d8d",
			wantFragments: []string{
				// oracle images use the 'opc' cloud user, and /8 means yum.
				"      DEFAULT_USERS=\"root cloud-user opc\"\n",
				`      retry_cmd "yum install -y qemu-guest-agent openssh-server curl ca-certificates" || true`,
			},
		},
		{
			name:            "rhel8",
			params:          IncusConfigVMParams{InstanceName: "vm-9", ImageAlias: "rhel/8", RootPassword: "pw"},
			wantUserData:    "38c927e2ee2c856efbf749fe5686435618e328027b25e0010d6540b8daee9188",
			wantNetworkData: "8780b98cc7ea201de3e6ac06b38aa89fe01a25cb470f5c01cc089192cec86c85",
			wantFragments: []string{
				// rhel.*8 IS an rhel8 alias for VMs (the container pattern omits it),
				// and the deduped user list has no second 'cloud-user'.
				"      DEFAULT_USERS=\"root cloud-user\"\n",
				`      retry_cmd "yum install -y qemu-guest-agent openssh-server curl ca-certificates" || true`,
			},
		},
		{
			name:            "centos8",
			params:          IncusConfigVMParams{InstanceName: "vm-10", ImageAlias: "centos/8", RootPassword: "pw"},
			wantUserData:    "da81a381b9f099309384edbaebf775654f7bb5d8bc758839769362ccafb23a31",
			wantNetworkData: "6b05c50fecacb3204e2b0b8b3d5fd7a6326b31deeda6cd4e17ac5cd870ab604e",
			wantFragments: []string{
				"      DEFAULT_USERS=\"root cloud-user centos\"\n",
				`      retry_cmd "yum install -y qemu-guest-agent openssh-server curl ca-certificates" || true`,
			},
		},
		{
			name:            "unknown-windows",
			params:          IncusConfigVMParams{InstanceName: "vm-11", ImageAlias: "windows/2022", RootPassword: "pw"},
			wantUserData:    "1c199bbc77a1a7eee2843294f83cf9c889352ac1d6d51d9a4728a18b4761aea4",
			wantNetworkData: "ec83abf38c61191188127b83c1f999bfb57a42ebf1cbe06923b151f49e1c8295",
			wantFragments: []string{
				// Unknown aliases fall through to family 'linux' with apt + sshd.
				"      DEFAULT_USERS=\"root\"\n      SSH_SERVICE=\"sshd\"\n",
				"      if [ \"linux\" != \"alpine\" ]; then\n",
			},
		},
		{
			name: "empty-dns-empty-v6-dns",
			params: IncusConfigVMParams{
				InstanceName: "vm-12", ImageAlias: "debian/12", RootPassword: "pw",
				Network: &IncusConfigStaticNetwork{IPAddress: "10.0.0.5/24", Gateway: "10.0.0.1", DNS: []string{}, IPv6Address: "2001:db8::9", IPv6DNS: []string{}},
			},
			wantUserData:    "5980b9b74454a65f1976b06338512fc488d539b2a9c9c41ece6efb135e601ca0",
			wantNetworkData: "da7ea8dbb87e0c2dd2f8dfb54a272c7a0bbfffd254f46c625d048db7a9bb5dff",
			wantFragments: []string{
				// VM semantics: an EMPTY list falls back to the defaults (the container
				// generator keeps an empty list empty).
				"        - 10.10.0.1\n",
				"        - 2606:4700:4700::1111\n        - 2001:4860:4860::8888\n",
				"      - 2001:db8::9/128\n",
			},
		},
		{
			name: "escaping-shell-and-yaml",
			params: IncusConfigVMParams{
				InstanceName: "vm-13", ImageAlias: "debian/12",
				// $ ` " ' and \ each exercise a different escaping pass.
				RootPassword: "a$b`c\"d'e\\f",
				// The key is emitted raw into the YAML list but double-quote escaped into
				// the shell variable.
				SSHKey:             incusConfigStrPtr("ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIExampleKeyBlobHere \"weird\" user@host"),
				ExtraShellCommands: "echo 'single'\necho \"double\"\ntouch /tmp/$HOME",
				Network: &IncusConfigStaticNetwork{
					IPAddress: "10.9.9.5/24", Gateway: "10.9.9.1", DNS: []string{"9.9.9.9"},
					IPv6Address: "2001:db8::13/64", IPv6DNS: []string{"2606:4700:4700::1111"},
				},
			},
			wantUserData:    "4c865987ed8b86abfcaaed674022e92192aba99b6216832efb2eadfde33527be",
			wantNetworkData: "dbf1c5ec36819c093fa7b3648354eb85601298e9286f1d36173083c86070a6ad",
			wantFragments: []string{
				// YAML single quotes are doubled, nothing else is touched.
				"- 'root:a$b`c\"d''e\\f'\n",
				// The shell uses single quotes, so the embedded quote becomes '"'"'.
				"ROOT_PASSWORD='a$b`c\"d'\"'\"'e\\f'\n",
				// Double-quoted shell context escapes only \ $ ` and ".
				"      SSH_KEY=\"ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIExampleKeyBlobHere \\\"weird\\\" user@host\"\n",
				"      echo 'single'\n      echo \"double\"\n      touch /tmp/$HOME\n",
				"      macaddress: \"02:2c:5c:99:89:d7\"\n",
			},
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			payload, err := IncusConfigGenerateVM(tc.params)
			if err != nil {
				t.Fatalf("IncusConfigGenerateVM: %v", err)
			}

			userData := payload.UserUserData
			if got := incusConfigSha256Hex(userData); got != tc.wantUserData {
				t.Errorf("user-data sha256 = %s, want %s\n--- actual payload ---\n%s", got, tc.wantUserData, userData)
			}
			networkConfig := payload.UserNetworkConfig
			if got := incusConfigSha256Hex(networkConfig); got != tc.wantNetworkData {
				t.Errorf("network-config sha256 = %s, want %s\n--- actual ---\n%q", got, tc.wantNetworkData, networkConfig)
			}

			for _, fragment := range tc.wantFragments {
				if !strings.Contains(userData, fragment) && !strings.Contains(networkConfig, fragment) {
					t.Errorf("payload is missing %q", fragment)
				}
			}
			for _, fragment := range tc.absentFragments {
				if strings.Contains(userData, fragment) || strings.Contains(networkConfig, fragment) {
					t.Errorf("payload unexpectedly contains %q", fragment)
				}
			}

			if !strings.HasPrefix(userData, "#cloud-config\n") {
				t.Errorf("user-data must start with the #cloud-config header, got %q", userData[:20])
			}
			if !strings.HasSuffix(userData, "\n") {
				t.Error("user-data must end with a newline")
			}
			if !strings.HasPrefix(networkConfig, "version: 2\nethernets:\n") {
				t.Errorf("network-config must be netplan v2, got %q", networkConfig)
			}
			if !strings.HasSuffix(networkConfig, "\n") {
				t.Error("network-config must end with a newline")
			}
		})
	}
}

func TestIncusConfigVMNetworkConfigEdgeCases(t *testing.T) {
	macs := VMNetworkGenerateMacs("edge")

	// A record with only an IPv6 address cannot be expressed in netplan v2 without
	// an IPv4 gateway, so the TypeScript emits DHCP instead.
	partial := &IncusConfigStaticNetwork{IPv6Address: "2001:db8::1/64"}
	if got := incusConfigVMGenerateNetworkConfig(partial, macs); got != incusConfigVMGenerateDHCPNetworkConfig(macs) {
		t.Errorf("ipv6-only network record must fall back to DHCP, got %q", got)
	}
	// Gateway without an address is the same case.
	partial = &IncusConfigStaticNetwork{Gateway: "10.0.0.1"}
	if got := incusConfigVMGenerateNetworkConfig(partial, macs); got != incusConfigVMGenerateDHCPNetworkConfig(macs) {
		t.Errorf("gateway-only network record must fall back to DHCP, got %q", got)
	}

	// The MAC match line is lowercased and the eth1 block disappears without IPv6.
	if got := incusConfigVMGenerateDHCPNetworkConfig(VMNetworkNicMacs{Eth0: "02:AA:BB:CC:DD:EE", Eth1: "02:11:22:33:44:55"}); !strings.Contains(got, `macaddress: "02:aa:bb:cc:dd:ee"`) || strings.Contains(got, "incus_eth1") {
		t.Errorf("dhcp network-config = %q", got)
	}

	// An IPv6 address WITH a prefix length is passed through untouched.
	static := &IncusConfigStaticNetwork{IPAddress: "10.0.0.5/24", Gateway: "10.0.0.1", IPv6Address: " 2001:db8::9/64 "}
	if got := incusConfigVMGenerateNetworkConfig(static, macs); !strings.Contains(got, "- 2001:db8::9/64\n") {
		t.Errorf("prefix length was not preserved: %q", got)
	}
}

func TestIncusConfigVMDetectOSInfo(t *testing.T) {
	cases := []struct {
		alias  string
		family IncusConfigVMOSFamily
		pkg    IncusConfigVMPackageManager
		init   IncusConfigVMInitSystem
		ssh    string
		shell  string
		users  []string
	}{
		{"ubuntu/noble", IncusConfigVMOSFamilyUbuntu, IncusConfigVMPackageManagerApt, IncusConfigVMInitSystemSystemd, "ssh", "/bin/bash", []string{"root", "ubuntu"}},
		{"debian/12", IncusConfigVMOSFamilyDebian, IncusConfigVMPackageManagerApt, IncusConfigVMInitSystemSystemd, "ssh", "/bin/bash", []string{"root", "debian"}},
		{"kali/2024.1", IncusConfigVMOSFamilyDebian, IncusConfigVMPackageManagerApt, IncusConfigVMInitSystemSystemd, "ssh", "/bin/bash", []string{"root", "debian"}},
		{"alpine/3.20", IncusConfigVMOSFamilyAlpine, IncusConfigVMPackageManagerApk, IncusConfigVMInitSystemOpenRC, "sshd", "/bin/ash", []string{"root"}},
		{"fedora/40", IncusConfigVMOSFamilyRhel, IncusConfigVMPackageManagerDnf, IncusConfigVMInitSystemSystemd, "sshd", "/bin/bash", []string{"root", "cloud-user", "fedora"}},
		{"almalinux/9", IncusConfigVMOSFamilyRhel, IncusConfigVMPackageManagerDnf, IncusConfigVMInitSystemSystemd, "sshd", "/bin/bash", []string{"root", "cloud-user", "almalinux"}},
		{"almalinux/8", IncusConfigVMOSFamilyRhel8, IncusConfigVMPackageManagerYum, IncusConfigVMInitSystemSystemd, "sshd", "/bin/bash", []string{"root", "cloud-user", "almalinux"}},
		{"rockylinux/8", IncusConfigVMOSFamilyRhel8, IncusConfigVMPackageManagerYum, IncusConfigVMInitSystemSystemd, "sshd", "/bin/bash", []string{"root", "cloud-user", "rocky"}},
		{"oracle/8", IncusConfigVMOSFamilyRhel8, IncusConfigVMPackageManagerYum, IncusConfigVMInitSystemSystemd, "sshd", "/bin/bash", []string{"root", "cloud-user", "opc"}},
		{"centos/8", IncusConfigVMOSFamilyRhel8, IncusConfigVMPackageManagerYum, IncusConfigVMInitSystemSystemd, "sshd", "/bin/bash", []string{"root", "cloud-user", "centos"}},
		// The VM pattern includes rhel.*8 (unlike the container pattern).
		{"rhel/8", IncusConfigVMOSFamilyRhel8, IncusConfigVMPackageManagerYum, IncusConfigVMInitSystemSystemd, "sshd", "/bin/bash", []string{"root", "cloud-user"}},
		{"rhel/9", IncusConfigVMOSFamilyRhel, IncusConfigVMPackageManagerDnf, IncusConfigVMInitSystemSystemd, "sshd", "/bin/bash", []string{"root", "cloud-user"}},
		{"UBUNTU/Noble", IncusConfigVMOSFamilyUbuntu, IncusConfigVMPackageManagerApt, IncusConfigVMInitSystemSystemd, "ssh", "/bin/bash", []string{"root", "ubuntu"}},
		{"windows/2022", IncusConfigVMOSFamilyLinux, IncusConfigVMPackageManagerApt, IncusConfigVMInitSystemSystemd, "sshd", "/bin/bash", []string{"root"}},
	}

	for _, tc := range cases {
		got := incusConfigVMDetectOSInfo(tc.alias)
		if got.Family != tc.family || got.PackageManager != tc.pkg || got.InitSystem != tc.init ||
			got.SSHServiceName != tc.ssh || got.DefaultShell != tc.shell {
			t.Errorf("%s → %+v", tc.alias, got)
		}
		if strings.Join(got.DefaultUsers, ",") != strings.Join(tc.users, ",") {
			t.Errorf("%s users = %v, want %v", tc.alias, got.DefaultUsers, tc.users)
		}
	}
}

func TestVMNetworkGenerateMacs(t *testing.T) {
	macs := VMNetworkGenerateMacs("vm-1")
	if macs.Eth0 != "02:a0:68:ba:c3:7d" || macs.Eth1 != "02:fc:e7:91:4f:38" {
		t.Fatalf("macs for vm-1 = %+v", macs)
	}

	// The derivation must stay identical to the copy that lib/network_payload_builder.go
	// has carried since before this module existed.
	builderEth0, builderEth1 := networkPayloadGenerateVmNicMacs("vm-1")
	if macs.Eth0 != builderEth0 || macs.Eth1 != builderEth1 {
		t.Errorf("VMNetworkGenerateMacs disagrees with networkPayloadGenerateVmNicMacs: %+v vs %s/%s", macs, builderEth0, builderEth1)
	}

	// Different seeds differ, and both addresses are locally administered unicast.
	other := VMNetworkGenerateMacs("vm-2")
	if other.Eth0 == macs.Eth0 || other.Eth1 == macs.Eth1 {
		t.Errorf("distinct seeds produced the same MACs: %+v vs %+v", macs, other)
	}
	for _, mac := range []string{macs.Eth0, macs.Eth1, other.Eth0, other.Eth1} {
		if len(mac) != 17 || !strings.HasPrefix(mac, "02:") {
			t.Errorf("mac %q must be a lowercase 0x02-prefixed address", mac)
		}
		for _, part := range strings.Split(mac, ":") {
			if len(part) != 2 || strings.ToLower(part) != part {
				t.Errorf("mac %q has a non-padded/non-lowercase octet %q", mac, part)
			}
		}
	}
	if VMNetworkGenerateMacs("vm-1") != macs {
		t.Error("MAC generation must be deterministic")
	}
}

// TestIncusConfigVMWiredIntoRouter pins the wiring: the VM branch of
// GenerateIncusConfig must produce a real VM payload instead of failing with
// ErrIncusConfigVMGeneratorMissing.
func TestIncusConfigVMWiredIntoRouter(t *testing.T) {
	network := &IncusConfigStaticNetwork{
		IPAddress: "10.10.1.100/24", Gateway: "10.10.1.1",
		IPv6Address: "2001:db8::100/64",
	}

	result, err := GenerateIncusConfig(IncusConfigParams{
		InstanceName: "vm-router", ImageAlias: "ubuntu/noble", RootPassword: "pw",
		Type: "virtual-machine", Network: network, NetworkMode: "nat_ipv6",
		SSHKey: incusConfigStrPtr("ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIExample"),
	})
	if err != nil {
		if errors.Is(err, ErrIncusConfigVMGeneratorMissing) {
			t.Fatalf("VM generator is not wired into GenerateIncusConfig: %v", err)
		}
		t.Fatalf("GenerateIncusConfig: %v", err)
	}

	// The router drops instanceIdSeed and seeds from the instance name, so the
	// router payload must equal the direct call with an empty seed.
	want, err := IncusConfigGenerateVM(IncusConfigVMParams{
		InstanceName: "vm-router", ImageAlias: "ubuntu/noble", RootPassword: "pw",
		Network: network, NetworkMode: "nat_ipv6",
		SSHKey: incusConfigStrPtr("ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIExample"),
	})
	if err != nil {
		t.Fatal(err)
	}
	if result.ConfigPayload != want {
		t.Errorf("router payload differs from the direct VM generator call")
	}

	// Metadata is rebuilt by the router (osFamily 'linux', sshPort 22).
	if result.MetaData.InstanceType != IncusConfigTypeVM {
		t.Errorf("instanceType = %q, want virtual-machine", result.MetaData.InstanceType)
	}
	if result.MetaData.OsFamily != IncusConfigOsFamilyLinux {
		t.Errorf("osFamily = %q, want linux", result.MetaData.OsFamily)
	}
	if result.MetaData.SSHPort != 22 || result.MetaData.IPAddress != "10.10.1.100/24" {
		t.Errorf("metadata = %+v", result.MetaData)
	}
	if !strings.Contains(result.ConfigPayload.UserUserData, "package_update: true") {
		t.Errorf("router VM payload does not look like a VM cloud-config")
	}

	// A container payload must never be produced for a VM: the VM user-data has no
	// timezone line (the container template has one).
	if strings.Contains(result.ConfigPayload.UserUserData, "timezone: Asia/Shanghai") {
		t.Error("VM branch returned the container template")
	}
}
